"$:/plugins/JorisL/PrintTemplates/styles/A4_print_template.css": {
    "created": "20260317215025208",
    "text": "@media print {
  /* Hide the default browser-generated headers and footers */
  @page {
    font-size: 10pt; /* size of headers and footers */
    size: A4 portrait;
    margin: 15mm; /* Adjust margins as needed */
  }

  /* Define your custom footer */
  .custom-header {
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    text-align: center;
    padding: 10px;
  }
	.custom-footer {
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    text-align: center;
    padding: 10px;
  }

  /* Ensure custom headers/footers do not overlap content */
  body {
    padding-bottom: 0px; /* Adjust based on footer height */
    padding-bottom: 40px; /* Adjust based on footer height */
  }
}

@media screen {
  /* Hide custom headers/footers from screen view */
  .custom-header .custom-footer {
    display: none;
  }
}


@page {
  @top-center {
    content: "";
  }
	@bottom-center {
    content: counter(page) "/" counter(pages);
  }
}",
    "title": "$:/plugins/JorisL/PrintTemplates/styles/A4_print_template.css",
    "type": "text/css",
    "tags": "$:/tags/Stylesheet",
    "modified": "20260317230231989"
}
,
"$:/plugins/JorisL/PrintTemplates/styles/common_print_template.css": {
    "created": "20260317215429873",
    "text": "@media print {
	*:not(code) {
		color: #000 !important;
		background: transparent !important;
		box-shadow: none !important;
	}

	pre, code {
		white-space: pre-wrap !important; /* Allows wrapping for long lines */
		word-break: break-all !important; /* Prevents overflow */
		box-shadow: none !important;      /* Remove any box-shadows */
		border: none !important; /* Remove any border */
	}

	table, figure {
    page-break-inside: avoid;
  }

	.tc-story-river{
		width: 100%;
	}

	/* Hide unwanted elements */
	[data-tiddler-title^="$:/"] {
		display: none;
	}
	header {display: none;}
	.commandpalette {display: none !important;}
	.tc-notification {display: none !important;}
	.crosslinks {display: none;}

	/* Single tiddler per page */
  .tc-tiddler-frame { break-after: page; }
  .tc-tiddler-frame:last-of-type { break-after: avoid; }
}",
    "title": "$:/plugins/JorisL/PrintTemplates/styles/common_print_template.css",
    "type": "text/css",
    "tags": "$:/tags/Stylesheet",
    "modified": "20260317225454748"
}
