"$:/plugins/JorisL/PrintTemplates/styles/slides_print_template.css": {
    "created": "20260317223229040",
    "text": "@media print {
  /* Hide the default browser-generated headers and footers */
  @page {
		font-size: 10pt; /* size of headers and footers */
    size: A4 landscape;
    margin: 15mm; /* Adjust margins as needed */

		@top-center {
			content: "";
		}
		@bottom-center {
			content: counter(page) "/" counter(pages);
		}
  }

  /* Define your custom footer */
  .custom-header {
    display: none;
  }
	.custom-footer {
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    text-align: center;
    padding: 10px;
  }

  /* Ensure custom headers/footers do not overlap content */
  body {
    padding-bottom: 0px; /* Adjust based on footer height */
    padding-bottom: 40px; /* Adjust based on footer height */
  }

	.tc-subtitle, /* hide subtitle*/
	.tc-tags-wrapper, /*hide tags */
	{
		display: none;
	}

	/* Add page break between H1 headers */
	h1 { break-before: page; }

